.page {
  padding: 128px 0 46px;
  background-color: #f6f5f1;
  background-image: radial-gradient(ellipse at 80% 15%, #dcebefa8, transparent 47%), linear-gradient(#d9e0df33 1px, transparent 1px), linear-gradient(90deg, #d9e0df33 1px, transparent 1px);
  background-size: auto, 42px 42px, 42px 42px;
}
.layout { width: min(1340px, calc(100% - 48px)); margin: auto; display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); }
.introduction { position: relative; min-width: 0; padding-right: 28px; }
.introduction h1 { font: 400 clamp(3.5rem, 5.4vw, 5.1rem)/.99 Georgia, serif; letter-spacing: -.045em; color: #0d304b; margin: 0 0 20px 28px; }
.description { max-width: 460px; margin: 0 0 12px 28px; color: #596c7e; font-size: 17px; line-height: 1.65; }
.tagline { position: absolute; top: 86px; right: 28px; margin: 0; width: fit-content; color: #123d5c; font: italic 24px/1.15 "Bradley Hand", "Segoe Print", cursive; transform: rotate(-8deg); }
.tagline svg { display: block; width: 64px; height: 44px; margin-left: 40px; stroke-width: 1.3; }
.artwork { margin-inline: -20px 0; }
.channels { position: relative; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; padding: 25px 18px; list-style: none; margin: -1px 0 0; border-radius: 24px; background: #faf9f5; box-shadow: 0 14px 30px #1a344b0b; }
.channels li { display: flex; align-items: center; gap: 9px; font-size: 13px; color: #102e49; line-height: 1.4; }
.channels svg { width: 30px; height: 34px; stroke-width: 1.5; flex-shrink: 0; color: #08778e; }
.closing { color: #123d5c; text-align: center; width: fit-content; margin: 25px auto 0; padding-bottom: 10px; border-bottom: 2px solid #12768c; font: italic 25px/1.25 "Bradley Hand", "Segoe Print", cursive; transform: rotate(-6deg); }
.right { border-left: 1px solid #c7d9df; padding: 20px 0 0 clamp(26px, 4vw, 68px); min-width: 0; }
.details { min-width: 0; padding: 0 28px 32px; }
.details h2 { font: 400 clamp(2.1rem, 3vw, 2.8rem)/1.3 Georgia, serif; color: #0d304b; margin: 15px 0 24px; }
.details p { margin: 10px 0; }
.link { max-width: 100%; align-items: flex-start; color: var(--navy); font-size: 16px; }
.icon { flex-shrink: 0; margin-top: .2em; color: var(--teal); }
.value { min-width: 0; overflow-wrap: anywhere; }
.formArea { position: relative; }
.formArea::before { content: ""; position: absolute; z-index: 1; top: 0; left: 28px; width: 80px; height: 3px; background: linear-gradient(90deg, #103650, #078da0); }
.formArea :global(.form-panel) { border-radius: 26px; padding: 34px 28px 28px; background: #ffffffee; box-shadow: 0 22px 40px #203a551a; }
.formArea :global(.form-grid) { gap: 20px; }
.formArea :global(.field) { gap: 7px; }
.formArea :global(.field input), .formArea :global(.field select), .formArea :global(.field textarea) { background: transparent; border: 1px solid #b5c8d7; border-radius: 10px; }
.formArea :global(.field textarea) { min-height: 112px; }
.formArea :global(.button) { display: flex; margin: 18px 0 0 auto; min-width: 200px; justify-content: center; }
.responseTime { text-align: center; font-size: 12px; color: #596c7e; margin: 18px 0 0; }
@media (max-width: 1050px) {
  .tagline { position: static; margin: 0 24px -8px auto; }
  .channels { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .details { padding-inline: 8px; }
  .introduction h1, .description { margin-left: 0; }
}
@media (max-width: 800px) {
  .page { padding-top: 116px; }
  .layout { width: calc(100% - 32px); grid-template-columns: minmax(0, 1fr); gap: 44px; }
  .introduction { padding-right: 0; }
  .artwork { margin-inline: 0; }
  .right { padding: 32px 0 0; border-left: 0; border-top: 1px solid #c7d9df; }
  .channels { gap: 20px; }
  .formArea :global(.form-panel) { padding: 28px 20px 24px; }
  .details { padding-bottom: 28px; }
  .description { max-width: 480px; }
}

