sources.app/globals.css:
@import "tailwindcss";

:root {
  --navy: #203a55;
  --navy-deep: #132c43;
  --teal: #227d91;
  --teal-dark: #17677a;
  --ink: #172b3a;
  --muted: #5f707c;
  --cream: #f6f5f1;
  --paper: #ffffff;
  --line: #dbe4e8;
  --mist: #e7ecef;
  --success: #166b55;
  --danger: #a63c37;
  --radius: 22px;
  --shadow: 0 22px 60px rgba(25, 51, 70, 0.12);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: var(--cream); color: var(--ink); font-family: Arial, Helvetica, sans-serif; line-height: 1.6; }
a { color: inherit; text-decoration: none; }
button, input, textarea, select { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
:focus-visible { outline: 3px solid #4fb4c8; outline-offset: 3px; }
::selection { color: white; background: var(--teal); }

.shell { width: min(1180px, calc(100% - 40px)); margin-inline: auto; }
.site-header { position: sticky; top: 0; z-index: 50; background: color-mix(in srgb, var(--cream) 92%, transparent); border-bottom: 1px solid rgba(32,58,85,.09); backdrop-filter: blur(16px); }
.header-inner { min-height: 78px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.brand { display: inline-flex; align-items: center; gap: 12px; font-size: .84rem; font-weight: 800; letter-spacing: .11em; color: var(--navy); }
.brand .brand-logo { width: 52px; height: 52px; border-radius: 8px; }
/* Preserve the supplied 500px PNG. Only empty alpha padding falls outside the
   frame: artwork bounds are (63,108)–(437,433); at 125% every painted pixel fits. */
.brand-logo { position: relative; display: inline-block; flex-shrink: 0; overflow: hidden; vertical-align: middle; background: #e9e5dd; }
.brand-logo > img { position: absolute; width: 125%; height: 125%; max-width: none; left: -12.5%; top: -17.625%; object-fit: contain; border: 0; border-radius: 0; padding: 0; background: transparent; }
.nav { display: flex; align-items: center; gap: 26px; font-size: .92rem; font-weight: 700; color: #405563; }
.nav a:hover { color: var(--teal-dark); }
.nav .button { color: white; }
.menu-button { display: none; border: 0; background: transparent; color: var(--navy); padding: 8px; }
.button { display: inline-flex; min-height: 48px; align-items: center; justify-content: center; gap: 9px; padding: 0 20px; border-radius: 999px; border: 1px solid transparent; background: var(--navy); color: white; font-weight: 800; cursor: pointer; transition: transform .2s ease, background .2s ease; }
.button:hover { transform: translateY(-2px); background: var(--navy-deep); }
.button-secondary { background: transparent; border-color: #9eb2bc; color: var(--navy); }
.button-secondary:hover { background: white; }
.button-small { min-height: 40px; padding-inline: 16px; font-size: .88rem; }
.button:disabled { opacity: .55; cursor: not-allowed; transform: none; }

.eyebrow { margin: 0 0 14px; color: var(--teal-dark); font-size: .75rem; font-weight: 900; letter-spacing: .17em; text-transform: uppercase; }
.display { margin: 0; color: var(--navy-deep); font-family: Georgia, 'Times New Roman', serif; font-size: clamp(3.2rem, 7vw, 6.7rem); font-weight: 500; letter-spacing: -.055em; line-height: .92; }
.display em { color: var(--teal); font-style: normal; }
.lede { max-width: 620px; margin: 24px 0 0; color: var(--muted); font-size: clamp(1rem, 2vw, 1.18rem); }
.hero { position: relative; min-height: 760px; overflow: clip; border-bottom: 1px solid var(--line); background: radial-gradient(circle at 78% 35%, #e1eff0 0, transparent 30%), var(--cream); }
.hero-grid { position: relative; z-index: 2; display: grid; grid-template-columns: .9fr 1.1fr; min-height: 690px; align-items: center; }
.hero-copy { position: relative; z-index: 3; padding: 80px 0 120px; }
.hero-copy .display { font-size: clamp(3.4rem, 6.3vw, 6.1rem); }
.hero-actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 32px; }
.hero-note { display: flex; align-items: center; gap: 10px; margin-top: 25px; color: #667985; font-size: .82rem; }
.hero-note::before { content: ''; width: 24px; height: 1px; background: var(--teal); }
.scene-wrap { position: absolute; inset: 72px max(0px, calc((100vw - 1240px) / 2)) 0 43%; z-index: 4; min-height: 620px; pointer-events: none; }
.scene-controls { position: absolute; right: 22px; top: 20px; z-index: 5; pointer-events: auto; }
.motion-toggle { display: inline-flex; gap: 8px; align-items: center; border: 1px solid rgba(32,58,85,.15); border-radius: 999px; background: rgba(255,255,255,.82); padding: 8px 12px; color: var(--navy); font-size: .75rem; font-weight: 800; box-shadow: 0 8px 28px rgba(22,50,70,.08); }
.scene-fallback { height: 100%; min-height: 560px; display: grid; place-items: center; }
.fallback-art { position: relative; width: min(620px, 90%); aspect-ratio: 1.35; border-radius: 45% 45% 14% 14%; background: linear-gradient(#e0eff1 0 58%, #cad5da 58% 63%, #70818b 63% 74%, #dfe6e7 74%); overflow: hidden; }
.fallback-truck { position: absolute; left: 18%; bottom: 24%; width: 57%; height: 26%; border-radius: 10px 18px 7px 7px; background: var(--navy); box-shadow: inset -28px 0 var(--teal); }
.fallback-truck::before { content:''; position:absolute; left:-22%; bottom:0; width:28%; height:76%; background:var(--teal); border-radius:24px 4px 5px 5px; }
.fallback-truck::after { content:''; position:absolute; left:-13%; bottom:-18px; width:34px; height:34px; border:8px solid #26333a; border-radius:50%; background:#8ea0a9; box-shadow:205px 0 0 -8px #8ea0a9, 205px 0 0 0 #26333a; }

.section { padding: 112px 0; }
.section-compact { padding: 76px 0; }
.section-white { background: white; }
.section-navy { background: var(--navy-deep); color: white; }
.section-head { display: flex; align-items: end; justify-content: space-between; gap: 30px; margin-bottom: 46px; }
.section-head h2, .page-hero h1 { margin: 0; color: var(--navy-deep); font-family: Georgia, 'Times New Roman', serif; font-size: clamp(2.4rem, 5vw, 4.4rem); font-weight: 500; letter-spacing: -.04em; line-height: 1; }
.section-head p { max-width: 500px; margin: 0; color: var(--muted); }
.cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.card { position: relative; padding: 36px; border: 1px solid var(--line); border-radius: var(--radius); background: white; box-shadow: 0 12px 35px rgba(26,54,74,.06); }
.card-dark { min-height: 370px; overflow: hidden; background: var(--navy); color: white; border-color: transparent; }
.card-dark:nth-child(2) { background: var(--teal-dark); }
.card h3 { margin: 22px 0 10px; color: inherit; font-family: Georgia, 'Times New Roman', serif; font-size: 2rem; font-weight: 500; }
.card p { margin: 0 0 24px; color: inherit; opacity: .78; }
.card-icon { display: grid; width: 50px; height: 50px; place-items: center; border: 1px solid currentColor; border-radius: 50%; opacity: .8; }
.text-link { display: inline-flex; align-items: center; gap: 7px; font-weight: 800; }
.card-orbit { position: absolute; width: 260px; height: 260px; right: -80px; bottom: -100px; border: 1px solid rgba(255,255,255,.2); border-radius: 50%; }
.card-orbit::before, .card-orbit::after { content:''; position:absolute; inset:30px; border:1px solid rgba(255,255,255,.15); border-radius:50%; }
.card-orbit::after { inset:70px; }
.steps { display: grid; grid-template-columns: repeat(4,1fr); border-top: 1px solid var(--line); }
.step { padding: 32px 26px 10px 0; }
.step-number { display: block; margin-bottom: 40px; color: var(--teal); font-size: .75rem; font-weight: 900; }
.step h3 { margin: 0 0 8px; color: var(--navy); font-size: 1rem; }
.step p { margin: 0; color: var(--muted); font-size: .92rem; }
.quote-band { display: grid; grid-template-columns: 1.2fr .8fr; align-items: center; gap: 30px; padding: 70px; border-radius: 32px; background: var(--navy-deep); color: white; }
.quote-band h2 { margin: 0; max-width: 700px; font-family: Georgia, serif; font-size: clamp(2.3rem, 5vw, 4rem); font-weight: 500; line-height: 1; }
.quote-band p { color: #c7d5dc; }
.quote-band .band-action { justify-self: end; }
.quote-band .button { background: #57b4c5; color: var(--navy-deep); }

.page-hero { padding: 100px 0 76px; border-bottom: 1px solid var(--line); background: radial-gradient(circle at 78% 20%, #ddecf0, transparent 30%); }
.page-hero h1 { max-width: 900px; }
.page-hero .lede { max-width: 720px; }
.content-grid { display: grid; grid-template-columns: .75fr 1.25fr; gap: 70px; }
.content-grid aside { color: var(--teal-dark); font-size: .78rem; font-weight: 900; letter-spacing: .13em; text-transform: uppercase; }
.prose h2 { margin: 0 0 18px; color: var(--navy); font-family: Georgia, serif; font-size: 2.1rem; font-weight: 500; }
.prose h3 { color: var(--navy); }
.prose p, .prose li { color: var(--muted); }
.prose section + section { margin-top: 54px; padding-top: 44px; border-top: 1px solid var(--line); }

.form-shell { display: grid; grid-template-columns: .7fr 1.3fr; gap: 60px; align-items: start; }
.form-panel { padding: 40px; border: 1px solid var(--line); border-radius: 26px; background: white; box-shadow: var(--shadow); }
.form-section { margin: 0 0 34px; padding: 0 0 30px; border: 0; border-bottom: 1px solid var(--line); }
.form-section:last-of-type { border-bottom: 0; }
.form-section legend { width: 100%; margin-bottom: 20px; color: var(--navy); font-family: Georgia, serif; font-size: 1.45rem; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.field { display: flex; flex-direction: column; gap: 7px; }
.field-full { grid-column: 1 / -1; }
.field label { color: #354b5a; font-size: .84rem; font-weight: 800; }
.field input, .field textarea, .field select { width: 100%; min-height: 50px; padding: 12px 14px; border: 1px solid #b9c8cf; border-radius: 10px; background: #fbfcfc; color: var(--ink); }
.field textarea { min-height: 118px; resize: vertical; }
.field small { color: var(--muted); }
.field-error { color: var(--danger) !important; font-size: .78rem; }
.form-status { margin: 20px 0; padding: 16px; border-radius: 10px; background: #e7f3ee; color: var(--success); }
.form-status.error { background: #f8eaea; color: var(--danger); }
.honeypot { position: absolute; left: -10000px; width: 1px; height: 1px; overflow: hidden; }
.side-note { position: sticky; top: 120px; }
.side-note h2 { margin: 0 0 15px; color: var(--navy); font-family: Georgia, serif; font-size: 2.2rem; font-weight: 500; }
.side-note p { color: var(--muted); }
.notice { padding: 18px 20px; border: 1px solid #bdd1d8; border-left: 4px solid var(--teal); border-radius: 10px; background: #edf5f6; color: #34515f; }

.faq-list { border-top: 1px solid var(--line); }
.faq-item { border-bottom: 1px solid var(--line); }
.faq-item summary { display: flex; justify-content: space-between; gap: 20px; padding: 25px 0; color: var(--navy); font-weight: 800; cursor: pointer; list-style: none; }
.faq-item summary::after { content:'+'; color:var(--teal); font-size:1.4rem; }
.faq-item[open] summary::after { content:'−'; }
.faq-item p { margin: -7px 0 28px; max-width: 780px; color: var(--muted); }

.site-footer { padding: 70px 0 28px; background: #10283c; color: white; }
.footer-grid { display: grid; grid-template-columns: 1.5fr repeat(2, .75fr); gap: 60px; }
.footer-brand p { max-width: 450px; color: #aebfc9; }
.footer-col h3 { margin-top: 0; font-size: .78rem; letter-spacing: .12em; text-transform: uppercase; color: #81c4cf; }
.footer-col a { display: block; margin: 9px 0; color: #d1dce1; font-size: .9rem; }
.footer-bottom { display: flex; justify-content: space-between; gap: 20px; margin-top: 58px; padding-top: 22px; border-top: 1px solid rgba(255,255,255,.12); color: #92a7b3; font-size: .78rem; }

.admin-body { background: #edf1f3; }
.admin-shell { display: grid; grid-template-columns: 250px 1fr; min-height: 100vh; }
.admin-nav { position: sticky; top: 0; height: 100vh; padding: 28px 22px; background: var(--navy-deep); color: white; }
.admin-nav .brand { color: white; }
.admin-links { display: grid; gap: 4px; margin-top: 38px; }
.admin-links a { padding: 10px 12px; border-radius: 8px; color: #bfd0d8; font-size: .9rem; }
.admin-links a:hover { background: rgba(255,255,255,.08); color: white; }
.admin-main { min-width: 0; padding: 42px; }
.admin-head { display:flex; justify-content:space-between; align-items:end; margin-bottom:28px; }
.admin-head h1 { margin:0; color:var(--navy); font-family:Georgia,serif; font-size:2.3rem; font-weight:500; }
.stat-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:16px; }
.stat { padding:24px; border:1px solid var(--line); border-radius:16px; background:white; }
.stat strong { display:block; color:var(--navy); font-size:2rem; }
.stat span { color:var(--muted); font-size:.82rem; }
.data-card { margin-top:22px; padding:24px; border:1px solid var(--line); border-radius:16px; background:white; overflow:auto; }
.data-card h2 { margin-top:0; color:var(--navy); font-size:1.1rem; }
.data-table { width:100%; border-collapse:collapse; font-size:.86rem; }
.data-table th { padding:12px; text-align:left; color:var(--muted); border-bottom:1px solid var(--line); }
.data-table td { padding:14px 12px; border-bottom:1px solid #edf1f3; white-space:nowrap; }
.pill { display:inline-block; padding:4px 9px; border-radius:999px; background:#e5f2f3; color:var(--teal-dark); font-size:.72rem; font-weight:800; text-transform:capitalize; }
.empty { padding:45px 20px; text-align:center; color:var(--muted); }
.setup-card { max-width:680px; padding:30px; border:1px solid #d7cba7; border-radius:16px; background:#fff9e7; }
.login-wrap { min-height:100vh; display:grid; place-items:center; padding:24px; background:var(--navy-deep); }
.login-card { width:min(440px,100%); padding:40px; border-radius:22px; background:white; box-shadow:var(--shadow); }
.login-card h1 { margin-top:0; color:var(--navy); font-family:Georgia,serif; font-weight:500; }

@media (max-width: 900px) {
