}

@media (max-width: 640px) {
  .shell { width:min(100% - 28px,1180px); }
  .header-inner { min-height:68px; }
  .brand { font-size:.72rem; }
  .nav { top:69px; }
  .hero { min-height:950px; }
  .hero-grid { min-height:910px; }
  .hero-copy { width:100%; padding:58px 0 0; }
  .hero-copy .display { font-size:clamp(3.15rem,16vw,4.5rem); }
  .hero-copy .lede { max-width:92%; font-size:.96rem; }
  .scene-wrap { inset:610px -100px -40px -90px; opacity:.82; min-height:330px; }
  .scene-controls { right:auto; left:104px; }
