  .section-head p { margin-top:18px; }
  .cards, .steps, .footer-grid, .quote-band { grid-template-columns:1fr; }
  .card { padding:26px; }
  .card-dark { min-height:310px; }
  .quote-band { padding:36px 26px; }
  .quote-band .band-action { justify-self:start; }
  .form-panel { padding:24px 18px; }
  .form-grid { grid-template-columns:1fr; }
  .field-full { grid-column:auto; }
  .footer-grid { gap:30px; }
  .footer-bottom { flex-direction:column; }
  .admin-links { display:flex; overflow-x:auto; }
  .admin-main { padding:20px 14px; }
  .stat-grid { grid-template-columns:1fr 1fr; gap:10px; }
