}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior:auto; }
  *, *::before, *::after { animation-duration:.01ms !important; animation-iteration-count:1 !important; transition-duration:.01ms !important; }
}

/* Immersive courier system */
:root {
  --scene-line: rgba(67, 187, 205, .34);
  --scene-glow: rgba(55, 177, 197, .18);
  --deep-shadow: 0 28px 80px rgba(8, 31, 48, .17), 0 4px 12px rgba(8, 31, 48, .08);
}

body { background: #f3f2ed; background-image: linear-gradient(rgba(32,58,85,.026) 1px, transparent 1px), linear-gradient(90deg, rgba(32,58,85,.026) 1px, transparent 1px); background-size: 42px 42px; }
.site-header { top: 10px; width: min(1240px, calc(100% - 24px)); margin: 10px auto 0; border: 1px solid rgba(255,255,255,.7); border-radius: 18px; background: rgba(247,246,241,.85); box-shadow: 0 16px 50px rgba(14,42,60,.1); }
.header-inner { min-height: 70px; padding-inline: 12px 14px; }
.brand .brand-logo { width: 48px; height: 48px; padding: 3px; border: 1px solid rgba(32,58,85,.13); border-radius: 10px; background: #e9e5dd; box-shadow: 0 7px 18px rgba(14,42,60,.14); object-fit: cover; }
.nav { gap: 20px; }
.nav > a:not(.button) { position: relative; padding-block: 10px; }
.nav > a:not(.button)::after { content: ""; position: absolute; left: 0; right: 100%; bottom: 5px; height: 2px; background: var(--teal); transition: right .24s ease; }
.nav > a:hover::after, .nav > a:focus-visible::after { right: 0; }
.nav .motion-toggle { margin-left: -6px; }
.header-inner > .motion-toggle { order: 2; }
.header-inner > .nav { order: 1; margin-left: auto; }
.header-inner > .menu-button { order: 3; }
.motion-toggle { cursor: pointer; transition: transform .2s ease, border-color .2s ease, background .2s ease; }
.motion-toggle:hover { transform: translateY(-2px); border-color: rgba(34,125,145,.5); }
.route-transition { position: fixed; z-index: 90; top: 0; left: 0; width: 100%; height: 3px; pointer-events: none; overflow: hidden; }
.route-transition span { display: block; width: 42%; height: 100%; border-radius: 99px; background: linear-gradient(90deg, transparent, var(--teal), #64d2df, transparent); animation: route-enter .72s cubic-bezier(.2,.8,.2,1) both; }
@keyframes route-enter { from { transform: translateX(-110%); } to { transform: translateX(350%); } }

.hero { min-height: 720px; margin-top: -90px; padding-top: 90px; isolation: isolate; background: radial-gradient(circle at 83% 32%, rgba(72,183,200,.19), transparent 31%), radial-gradient(circle at 64% 70%, rgba(255,255,255,.9), transparent 35%), #f2f1ec; }
.hero::before { content: ""; position: absolute; z-index: 0; inset: 18% -6% -25% 44%; border: 1px solid var(--scene-line); border-radius: 50%; transform: rotate(-11deg); box-shadow: 0 0 0 38px rgba(34,125,145,.025), 0 0 0 78px rgba(34,125,145,.018); }
.hero-grid { min-height: 650px; grid-template-columns: .82fr 1.18fr; }
.hero-copy { max-width: 590px; padding: 112px 0 110px; }
.hero-copy .display { font-size: clamp(3.4rem, 6vw, 6.25rem); line-height: .91; }
.hero-support { margin: 22px 0 0; color: var(--navy); font-size: clamp(1.25rem, 2.2vw, 1.85rem); font-weight: 800; letter-spacing: -.025em; }
.hero-copy .lede { margin-top: 13px; max-width: 550px; }
.hero-scene { position: absolute; z-index: 1; top: 72px; right: max(-90px, calc((100vw - 1380px) / -2)); bottom: 18px; left: 42%; min-height: 600px; }

.scene-stage { position: relative; min-height: 480px; overflow: hidden; border: 1px solid rgba(255,255,255,.62); border-radius: 34px; background: radial-gradient(circle at 52% 25%, rgba(255,255,255,.92), rgba(215,233,233,.52) 44%, rgba(196,215,218,.6)); box-shadow: var(--deep-shadow); isolation: isolate; }
.scene-stage::after { content: ""; position: absolute; z-index: 3; inset: auto 8% 6% 8%; height: 20%; border-radius: 50%; background: rgba(20,50,70,.12); filter: blur(32px); pointer-events: none; }
.scene-stage canvas { position: relative; z-index: 2; width: 100% !important; height: 100% !important; min-height: inherit; }
.scene-stage-compact { min-height: 330px; border-radius: 26px; }
.scene-horizon { position: absolute; z-index: 1; left: 7%; right: 7%; bottom: 20%; height: 1px; background: linear-gradient(90deg, transparent, rgba(34,125,145,.3), transparent); }
.scene-caption { position: absolute; z-index: 5; right: 18px; bottom: 14px; color: rgba(20,48,65,.54); font-size: .64rem; font-weight: 800; letter-spacing: .11em; text-transform: uppercase; pointer-events: none; }
.page-hero-international .scene-stage, .site-footer .scene-stage, .login-wrap .scene-stage { border-color: rgba(88,190,207,.18); background: radial-gradient(circle at 58% 32%, #174967, #091d2e 64%, #061622); }
.page-hero-international { color: white; background: radial-gradient(circle at 78% 22%, rgba(43,150,173,.3), transparent 35%), #0b2539; }
.page-hero-international h1 { color: white; }
.page-hero-international .lede { color: #b8ccd5; }
.page-hero-international .eyebrow { color: #66cad9; }
.page-hero-international .scene-caption, .site-footer .scene-caption, .login-wrap .scene-caption { color: rgba(196,230,236,.48); }

.page-hero { min-height: 610px; margin-top: -90px; padding: 150px 0 64px; overflow: hidden; }
.page-hero-grid { display: grid; grid-template-columns: minmax(0, .9fr) minmax(420px, 1.1fr); gap: 56px; align-items: center; }
.page-hero-copy { position: relative; z-index: 4; }
.page-hero h1 { max-width: 650px; font-size: clamp(2.7rem, 5vw, 4.85rem); }
.page-hero .scene-stage { min-height: 390px; box-shadow: none; border-color: rgba(255,255,255,.38); background-color: transparent; }

.journey-section .scene-stage, .process-section .scene-stage { margin-bottom: 24px; }
.journey-section .cards { margin-top: -78px; position: relative; z-index: 5; padding: 0 24px; }
.dimensional-card { min-height: 350px; transform-style: preserve-3d; transition: transform .35s cubic-bezier(.2,.8,.2,1), box-shadow .35s ease; box-shadow: 0 30px 56px rgba(8,34,52,.2); }
.dimensional-card:hover, .dimensional-card:focus-visible { transform: perspective(1000px) rotateX(2deg) rotateY(-2deg) translateY(-8px); box-shadow: 0 40px 70px rgba(8,34,52,.3); }
.dimensional-card:nth-child(2):hover, .dimensional-card:nth-child(2):focus-visible { transform: perspective(1000px) rotateX(2deg) rotateY(2deg) translateY(-8px); }
.dimensional-card > * { position: relative; z-index: 2; }
.mini-road, .mini-globe { position: absolute; z-index: 1; right: 24px; top: 27px; width: 138px; height: 98px; opacity: .65; transform: translateZ(28px); pointer-events: none; }
.mini-road { border-bottom: 18px solid rgba(255,255,255,.25); border-radius: 0 0 55% 45%; transform: rotate(-8deg) translateZ(28px); }
.mini-road span { position: absolute; right: 18px; bottom: -9px; width: 48px; height: 24px; border-radius: 6px 10px 4px 4px; background: #66c4d2; box-shadow: inset -16px 0 rgba(255,255,255,.25); }
.mini-road i { position: absolute; right: 22px; bottom: -14px; width: 12px; height: 12px; border: 3px solid #0d2639; border-radius: 50%; box-shadow: 26px 0 0 -3px #68808a, 26px 0 0 0 #0d2639; }
.mini-globe { width: 94px; height: 94px; border: 1px solid rgba(255,255,255,.35); border-radius: 50%; background: repeating-radial-gradient(ellipse at 30% 35%, transparent 0 8px, rgba(255,255,255,.16) 9px 10px); box-shadow: inset -18px -10px 30px rgba(3,26,41,.3), 0 16px 28px rgba(3,20,31,.22); }
.mini-globe::before { content: ""; position: absolute; inset: 42% -24%; height: 1px; background: #8be1e9; transform: rotate(-17deg); box-shadow: 0 0 9px #5ed0dc; }
.mini-globe span { position: absolute; right: -21px; top: 14px; width: 36px; height: 6px; background: white; border-radius: 50% 90% 45% 50%; transform: rotate(-16deg); }
.steps { position: relative; margin-top: -60px; padding: 44px 22px 18px; border: 1px solid rgba(32,58,85,.1); border-radius: 26px; background: rgba(255,255,255,.83); box-shadow: 0 25px 60px rgba(18,48,68,.1); backdrop-filter: blur(16px); }
.step + .step { border-left: 1px solid var(--line); padding-left: 24px; }
.step svg { color: var(--teal); }

.side-note .scene-stage { min-height: 300px; margin: 26px 0; }
.form-panel { position: relative; border-color: rgba(32,58,85,.12); box-shadow: var(--deep-shadow); }
.form-panel::before { content: ""; position: absolute; top: -1px; left: 28px; width: 84px; height: 3px; border-radius: 5px; background: linear-gradient(90deg, var(--navy), var(--teal)); }
.field input:focus, .field textarea:focus, .field select:focus { border-color: var(--teal); box-shadow: 0 0 0 4px rgba(34,125,145,.1); outline: 2px solid #188594; outline-offset: 3px; }
.faq-list { perspective: 1200px; }
.faq-item { position: relative; margin: 12px 0; padding: 0 24px; border: 1px solid rgba(32,58,85,.11); border-radius: 14px; background: white; box-shadow: 0 12px 34px rgba(20,49,67,.07); transform-origin: top; transition: transform .25s ease, box-shadow .25s ease; }
.faq-item::before { content: "VKC"; position: absolute; right: 66px; top: 21px; color: rgba(34,125,145,.28); font-size: .65rem; font-weight: 900; letter-spacing: .15em; }
.faq-item[open] { transform: translateZ(12px) translateX(4px); box-shadow: 0 20px 46px rgba(20,49,67,.12); }

.quote-band { position: relative; overflow: hidden; border: 1px solid rgba(100,207,221,.18); box-shadow: 0 34px 80px rgba(7,30,46,.27); }
.quote-band::after { content: ""; position: absolute; right: -90px; top: -150px; width: 390px; height: 390px; border: 1px solid rgba(88,200,216,.26); border-radius: 50%; box-shadow: 0 0 0 42px rgba(88,200,216,.04), 0 0 0 86px rgba(88,200,216,.025); }
.quote-band > * { position: relative; z-index: 2; }

.site-footer { position: relative; overflow: hidden; padding-top: 84px; background: #071d2d; }
.footer-grid { grid-template-columns: 1.55fr .7fr .7fr; }
.footer-brand .scene-stage { min-height: 210px; margin-top: 28px; border-radius: 20px; box-shadow: none; }
.footer-logo { color: white; }
.footer-logo .brand-logo { width: 66px; height: 66px; }

.admin-body { background: radial-gradient(circle at 85% 10%, rgba(60,177,196,.13), transparent 27%), #e9eef0; }
.admin-nav { margin: 12px; height: calc(100vh - 24px); border: 1px solid rgba(255,255,255,.08); border-radius: 20px; box-shadow: 18px 0 55px rgba(11,34,50,.14); background: linear-gradient(150deg, #173b56, #091f31 70%); }
.admin-brand .brand-logo { width: 48px; height: 48px; }
.admin-links a { border: 1px solid transparent; }
.admin-links a:hover, .admin-links a:focus-visible { border-color: rgba(106,201,214,.18); background: linear-gradient(90deg, rgba(85,190,206,.14), rgba(255,255,255,.03)); transform: translateX(3px); }
.admin-owner { position: absolute; bottom: 20px; max-width: 200px; color: #8da4af; font-size: 11px; overflow-wrap: anywhere; }
.stat, .data-card { border-color: rgba(32,58,85,.1); border-radius: 18px; box-shadow: 0 17px 42px rgba(20,49,67,.07); }
.stat { position: relative; overflow: hidden; }
.stat::after { content: ""; position: absolute; right: -30px; bottom: -45px; width: 100px; height: 100px; border: 1px solid rgba(34,125,145,.18); border-radius: 50%; }
.login-wrap { position: relative; grid-template-columns: minmax(460px, 1fr) minmax(380px, 520px); gap: 46px; padding: 54px max(28px, calc((100vw - 1280px)/2)); overflow: hidden; }
.login-scene { width: 100%; }
.login-scene .scene-stage { min-height: 620px; box-shadow: 0 38px 100px rgba(0,0,0,.28); }
.login-card { position: relative; z-index: 4; width: 100%; border: 1px solid rgba(255,255,255,.8); box-shadow: 0 35px 100px rgba(2,16,25,.3); }
.login-card h1 { font-size: clamp(2.3rem, 4vw, 3.5rem); line-height: 1; letter-spacing: -.035em; }
.login-logo { width: 88px; height: 88px; margin-bottom: 22px; padding: 5px; border: 1px solid var(--line); border-radius: 16px; box-shadow: 0 12px 30px rgba(19,49,67,.16); object-fit: cover; }

.scene-fallback { position: relative; min-height: inherit; overflow: hidden; background: radial-gradient(circle at 50% 34%, rgba(255,255,255,.95), rgba(201,220,222,.85)); }
.scene-fallback-international, .scene-fallback-footer, .scene-fallback-admin { background: radial-gradient(circle at 50% 34%, #1b5875, #081d2c); }
.fallback-route { position: absolute; left: 12%; right: 12%; bottom: 26%; height: 22%; border-top: 3px solid #4ab9ca; border-radius: 50%; transform: rotate(-6deg); }
.fallback-box { position: absolute; left: 53%; bottom: 28%; width: 72px; height: 62px; border-radius: 5px; background: #b7895f; box-shadow: inset 0 9px #dec49a, 0 20px 28px rgba(13,40,55,.18); transform: rotate(-5deg); }
.fallback-vehicle { position: absolute; left: 17%; bottom: 22%; width: 44%; height: 22%; border-radius: 14px 22px 8px 8px; background: linear-gradient(90deg, var(--teal) 0 25%, var(--navy) 25%); box-shadow: inset 0 -8px rgba(0,0,0,.1), 0 22px 35px rgba(10,34,49,.25); }
.fallback-vehicle::before { content: ""; position: absolute; left: 8%; top: 14%; width: 14%; height: 28%; border-radius: 4px; background: #a9d5dc; }
.fallback-vehicle::after { content: ""; position: absolute; left: 15%; bottom: -15px; width: 30px; height: 30px; border: 7px solid #18262d; border-radius: 50%; background: #91a4ab; box-shadow: 190px 0 0 -7px #91a4ab, 190px 0 0 0 #18262d; }

@media (max-width: 1050px) {
  .nav { gap: 13px; font-size: .82rem; }
  .nav .motion-toggle span { display: none; }
  .page-hero-grid { grid-template-columns: .88fr 1.12fr; gap: 28px; }
