@media (max-width: 640px) {
  .site-header { width: calc(100% - 12px); border-radius: 14px; }
  .header-inner { min-height: 60px; padding-inline: 6px 8px; }
  .header-inner { gap: 8px; }
  .header-inner > .motion-toggle { min-width: 40px; padding-inline: 10px; margin-left: auto; }
  .header-inner > .motion-toggle span { display: none; }
  .brand .brand-logo { width: 43px; height: 43px; }
  .nav { top: 72px; inset-inline: 10px; }
  .hero { min-height: 1040px; }
  .hero-grid { min-height: 960px; }
  .hero-copy { width: 100%; padding: 80px 0 0; }
  .hero-copy .display { font-size: clamp(3rem, 15.5vw, 4.4rem); }
  .hero-support { font-size: 1.22rem; }
  .hero-note { margin-top: 17px; }
  .hero-scene { top: 630px; right: -86px; bottom: 18px; left: -54px; min-height: 365px; border: 0; border-radius: 26px; background: transparent; box-shadow: none; }
  .scene-caption { right: 12px; bottom: 9px; font-size: .52rem; }
