.site-header .nav { position: static; inset: auto; display: flex; flex-direction: row; align-items: center; gap: 20px; margin-left: auto; padding: 0; border: 0; border-radius: 0; box-shadow: none; background: transparent; font-size: .92rem; }
.site-header .nav a { white-space: normal; }
