@container (max-width: 64rem) {
  .site-header .header-inner { width: 100%; gap: 12px; padding: 8px 12px; }
  .site-header .brand { flex: 1; }
  .site-header .menu-button { display: inline-flex; }
  .site-header .nav { position: absolute; inset: calc(100% + 8px) 0 auto; display: none; flex-direction: column; align-items: stretch; gap: 6px; margin: 0; padding: 16px; border: 1px solid var(--line); border-radius: 14px; background: var(--cream); color: var(--navy); box-shadow: var(--shadow); max-height: calc(100dvh - var(--header-height, 100px) - 32px); overflow-y: auto; overscroll-behavior: contain; }
  .site-header .nav.open { display: flex; }
  .site-header .nav a { flex-shrink: 0; min-height: 44px; padding: 8px 12px; overflow-wrap: anywhere; }
  .site-header .nav a:not(.button) { color: var(--navy); }
  .site-header .nav .button { color: white; }
}

/* Preserve image frames while displaying standalone local photographs. */
.photo-fill, .cinematic-hero-background { position: absolute; inset: 0; width: 100%; height: 100%; }
.editorial-image .photo-contain, .page-hero-image .photo-contain { object-fit: contain; object-position: center; }
.service-photo { position: relative; overflow: hidden; border-radius: inherit; background: #e8eded; }
.service-photo img { display: block; width: 100%; height: auto; }
.about-network-image, .about-thumbnail { background: #e8eded; }
@media (max-width: 900px) {
  .cinematic-hero-background { object-fit: contain; object-position: center bottom; }
}

/* Photograph-only frames follow native source ratios; logos and the stationary
   homepage background have their own sizing rules. */
[data-photo-frame] { position: relative; align-self: center; min-width: 0; min-height: 0; padding: 0; overflow: hidden; isolation: isolate; transition: transform 600ms cubic-bezier(.2,.7,.25,1); }
[data-photo-frame] > img { position: static; display: block; width: 100%; height: auto; object-fit: contain; }
[data-photo-frame]::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at var(--photo-x,50%) var(--photo-y,50%),rgba(198,255,250,.32),transparent 62%); opacity: 0; transition: opacity 600ms; }
[data-photo-hover]::after { opacity: 1; }
.image-feedback-layer { position: absolute; z-index: 4; pointer-events: none; user-select: none; }
.image-feedback-ripple { width: 116px; height: 116px; transform: translate(-50%,-50%); border-radius: 50%; border: 3px solid #42e0cf; background: radial-gradient(circle,rgba(63,213,197,.55),rgba(34,163,169,.25) 58%,transparent 70%); box-shadow: 0 0 0 2px rgba(239,255,255,.8); }
/* Match the replaced orbital area's height so Quote text and form stay put. */
.quote-media { position: relative; height: 330px; min-width: 0; display: grid; place-items: center; overflow: hidden; isolation: isolate; contain: layout paint; }
.quote-photo { width: min(423px,calc(100% - 48px)); border-radius: 8px; box-shadow: 0 12px 28px #0c27372b; }
.quote-bubble-canvas, .quote-bubble-fallback { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 2; }
.quote-bubble-fallback i { position: absolute; width: 40px; aspect-ratio: 1; border-radius: 50%; border: 1px solid #a7d4d4; background: radial-gradient(circle at 28% 24%,#ffffffed,#abd9d35e 32%,#267e8552 73%,#d6f4e2ab); box-shadow: inset -4px -5px 9px #194f5c26,0 5px 12px #194f5c14; }
.quote-bubble-fallback i:nth-child(1) { left: 4%; top: 18%; }
.quote-bubble-fallback i:nth-child(2) { right: 4%; top: 13%; width: 30px; }
.quote-bubble-fallback i:nth-child(3) { left: 5%; bottom: 11%; width: 24px; }
.quote-bubble-fallback i:nth-child(4) { right: 4%; bottom: 14%; width: 44px; }
[data-bubbles="webgl"] .quote-bubble-fallback { visibility: hidden; }
@media (max-width: 900px) { .quote-media { height: 210px; } .quote-photo { width: min(243px,calc(100% - 48px)); } }
@media (prefers-reduced-motion: reduce) {
  [data-photo-frame] { transform: none !important; transition: none; }
  [data-photo-frame]::after { transition: none; opacity: 0; }
  .quote-bubble-canvas { visibility: hidden; }
  [data-bubbles="webgl"] .quote-bubble-fallback { visibility: visible; }
}

/* The shared 3:2 crop applies only to the four homepage process photographs. */
